import org.junit.jupiter.api.io.TempDir;
import java.nio.file.*;

class FileExporterTest {

    @Test
    void writesCsvFile(@TempDir Path tempDir) throws Exception {   // per-test dir
        Path out = tempDir.resolve("orders.csv");
        new FileExporter().export(List.of("a,1", "b,2"), out);
        assertTrue(Files.exists(out));
        assertEquals(2, Files.readAllLines(out).size());
        // JUnit deletes tempDir automatically after this test
    }

    @TempDir static Path sharedDir;   // one dir shared across the class

    @Test
    void usesSharedDir() throws Exception {
        Files.writeString(sharedDir.resolve("note.txt"), "hi");
        assertTrue(Files.exists(sharedDir.resolve("note.txt")));
    }
}
