import org.junit.jupiter.api.TestInstance;
import org.junit.jupiter.api.TestInstance.Lifecycle;

@TestInstance(Lifecycle.PER_CLASS)     // one instance for all tests
class ReportTest {
    private ReportTemplate template;    // shared instance field

    @BeforeAll
    void loadTemplateOnce() {           // non-static now allowed
        template = ReportTemplate.loadExpensiveOnce();
    }

    @BeforeEach
    void resetState() {                 // reset mutable state to stay independent
        template.clearBuffer();
    }

    @Test void rendersHeader() { /* uses shared template */ }
}
